{% set project = frappe.get_doc('Real Estate Project', doc.project) %}
{% set unit = frappe.get_doc('Real Estate Unit', doc.unit) %}
{% set currency = frappe.db.get_value('Company', doc.company, 'default_currency') %}
{% set plans = frappe.get_all('Installment Plan', filters={'sales_agreement': doc.name, 'docstatus': ['!=', 2]}, fields=['name', 'plan_no', 'frequency'], order_by='modified desc', limit_page_length=1) %}
{% set plan = frappe.get_doc('Installment Plan', plans[0].name) if plans else None %}
<div class="agreement">
<div class="title">DETAILED AGREEMENT FOR SALE</div><div class="subtitle">Agreement No. {{ doc.agreement_no or doc.name }} | Executed on {{ frappe.utils.formatdate(doc.agreement_date) }}</div>
<h3>Parties and Recitals</h3><p><strong>Seller/Developer:</strong> {{ doc.seller_legal_name or doc.company }}{% if doc.seller_address %}, {{ doc.seller_address }}{% endif %}. <strong>Buyer:</strong> {{ doc.buyer_name or doc.customer }}{% if doc.buyer_address %}, {{ doc.buyer_address }}{% endif %}. The Seller/Developer agrees to sell and the Buyer agrees to purchase the unit described below, together with the rights expressly stated in this Agreement, the Property Booking and the attached schedules.</p>
<table><tr><th>Authorized Signatory</th><td>{{ doc.authorized_signatory or '' }}</td><th>Buyer NID / Passport</th><td>{{ doc.buyer_nid_passport or '' }}</td></tr><tr><th>Buyer Phone</th><td>{{ doc.buyer_phone or '' }}</td><th>Buyer Email</th><td>{{ doc.buyer_email or '' }}</td></tr></table>
<h3>1. Property, Project and Land Share</h3>{% if doc.get('property_description') %}{{ doc.property_description }}<p><strong>Parking / Ancillary Space:</strong> {{ doc.parking_details or 'Not specified in the agreement.' }}</p>{% else %}<table><tr><th>Project</th><td>{{ project.project_name or doc.project }}</td><th>Project Address</th><td>{{ project.address or project.location or '' }}</td></tr><tr><th>Unit</th><td>{{ unit.unit_no or doc.unit }}</td><th>Building / Floor</th><td>{{ unit.building or '' }} / {{ unit.floor or '' }}</td></tr><tr><th>Unit Type</th><td>{{ unit.unit_type or '' }}{% if unit.unit_category %} / {{ unit.unit_category }}{% endif %}</td><th>Area</th><td>{{ unit.area_sqft or 0 }} Sq. Ft.</td></tr><tr><th>Land Parcel / Share</th><td>{{ unit.land_parcel or 'As per title documents' }}</td><th>Proportionate Land</th><td>{% if unit.proportionate_land_area %}{{ unit.proportionate_land_area }}{% endif %}{% if unit.land_share_percent %} ({{ unit.land_share_percent }}%){% endif %}</td></tr><tr><th>Parking / Ancillary Space</th><td colspan="3">{{ doc.parking_details or 'Not included unless specifically stated.' }}</td></tr></table>{% endif %}
<h3>2. Price, Down Payment and Charges</h3><table><tr><th>Gross Contract Value</th><td>{{ frappe.utils.fmt_money(doc.contract_value or 0, currency=currency) }}</td><th>Discount</th><td>{{ frappe.utils.fmt_money(doc.discount or 0, currency=currency) }}</td></tr><tr><th>Net Contract Value</th><td>{{ frappe.utils.fmt_money(doc.net_contract_value or 0, currency=currency) }}</td><th>Down Payment / Booking Money</th><td>{{ frappe.utils.fmt_money(doc.booking_money or 0, currency=currency) }}</td></tr><tr><th>Balance Payable</th><td>{{ frappe.utils.fmt_money((doc.net_contract_value or 0) - (doc.booking_money or 0), currency=currency) }}</td><th>Registration / Transfer Costs</th><td>{{ doc.registration_cost_borne_by or 'As agreed' }}</td></tr></table><div class="terms">{{ doc.payment_instructions or 'Payments must be made only through the Seller/Developer’s approved payment channel. Amounts, taxes, utility/security deposits and charges are included or excluded only where expressly stated in writing.' }}</div>
<h3>3. Installment Schedule</h3><p>{% if plan %}Linked Plan: <strong>{{ plan.plan_no or plan.name }}</strong> ({{ plan.frequency or 'Custom' }}).{% endif %} Each payment is due on the stated date and is recognised only against an approved receipt.</p><table><thead><tr><th>Sl.</th><th>Due Date</th><th>Milestone / Description</th><th class="right">Installment</th><th class="right">Other Charges</th><th class="right">Total</th></tr></thead><tbody>{% if plan and plan.installments %}{% for row in plan.installments %}<tr><td>{{ row.installment_no or loop.index }}</td><td>{{ frappe.utils.formatdate(row.due_date) if row.due_date else '' }}</td><td>{{ row.description or '' }}</td><td class="right">{{ frappe.utils.fmt_money(row.principal or 0, currency=currency) }}</td><td class="right">{{ frappe.utils.fmt_money(row.other_charges or 0, currency=currency) }}</td><td class="right">{{ frappe.utils.fmt_money(row.total_amount or 0, currency=currency) }}</td></tr>{% endfor %}{% else %}<tr><td colspan="6" class="center">No installment plan linked. Attach an approved Installment Plan before execution.</td></tr>{% endif %}</tbody></table>
<h3>4. Facilities, Specifications and Common Services</h3><div class="terms">{{ doc.included_facilities or unit.description or 'Facilities, finishes, equipment and common-area services are limited to the approved specifications and written inclusions supplied by the Seller/Developer.' }}</div>
<h3>5. Handover, Utilities and Warranty</h3><ol><li><strong>Expected Handover:</strong> {{ frappe.utils.formatdate(doc.possession_date) if doc.possession_date else 'As notified by the Seller/Developer' }}, after all dues, documentation and agreed handover requirements are satisfied.</li><li><strong>Handover Conditions:</strong> {{ doc.handover_conditions or 'The Buyer shall inspect the unit and sign the handover record after clearing all payable amounts and completing required documents.' }}</li><li><strong>Utilities and Maintenance:</strong> {{ doc.utility_maintenance_terms or 'Utility connection, consumption charges, service charge, maintenance contribution and common-area rules apply as agreed in writing.' }}</li><li><strong>Defect Liability / Warranty:</strong> {{ doc.defect_liability_terms or 'Defect reporting and rectification will follow the agreed written warranty policy.' }}</li></ol>
<h3>6. Default, Cancellation, Registration and Notices</h3><ol><li><strong>Late Payment / Default:</strong> {{ doc.payment_default_terms or 'Any late-payment charge, notice period and remedies must be agreed in writing and permitted by applicable law.' }}</li><li><strong>Cancellation / Refund:</strong> {{ doc.cancellation_refund_terms or 'Cancellation, deductions and refunds will follow the executed agreement and applicable law.' }}</li><li><strong>Registration, Title and Documents:</strong> {{ doc.registration_document_terms or 'Registration, mutation, transfer and utility documentation will be completed on the conditions agreed by the parties.' }}</li><li><strong>Notices and Disputes:</strong> {{ doc.dispute_resolution_terms or 'Notices shall be served at the addresses above. The parties will first seek good-faith resolution, then follow the process agreed in writing and applicable law.' }}</li></ol>
{% if doc.annexure_documents %}<h3>7. Annexures and Documents Forming Part of This Agreement</h3><div class="terms">{{ doc.annexure_documents }}</div>{% endif %}{% if doc.special_terms %}<h3>8. Special Commercial Terms</h3><div class="terms">{{ doc.special_terms }}</div>{% endif %}{% if doc.terms %}<h3>9. Additional Terms</h3><div class="terms">{{ doc.terms }}</div>{% endif %}
<p class="note"><strong>Review before execution:</strong> This configurable business template must be reviewed and completed by a qualified Bangladesh legal adviser, including title/land records, statutory costs, registration, tax and project-specific clauses, before signing or registration.</p>
<div class="signatures"><div><div class="line"></div><strong>For the Seller / Developer</strong><br>{{ doc.authorized_signatory or 'Authorized Signatory' }}</div><div><div class="line"></div><strong>Buyer</strong><br>{{ doc.buyer_name or doc.customer }}</div><div><div class="line"></div><strong>Witness 1</strong><br>Name, address and signature</div><div><div class="line"></div><strong>Witness 2</strong><br>Name, address and signature</div></div></div>
